/** The osiedle name under (x, z) ('Stare Miasto', 'Jeżyce', 'Łazarz', …), or null outside every district ring */
function districtAt(x, z) {
  for (const d of DISTRICTS) {
    if (x < d.minX || x > d.maxX || z < d.minZ || z > d.maxZ) continue;
    if (pointInPoly(d.ring, x, z)) return d.name;
  }
  return null;
}
